	private static final String INDEX = TelemetryMetricNames.INDEX_LOOKUP_COUNT_ACTUAL;

	@Test
	void genuineLegacyAbsentIndexMetricRemainsUnknown() throws Exception {
		SingletonSet restored = readFixture("legacy-singleton-index-unknown.ser");
		assertEquals(-1L, restored.getLongMetricActual(INDEX), "an absent primitive and map entry mean unknown");
		assertFalse(restored.getLongMetricsActual().containsKey(INDEX), "reading the map must not invent zero work");
		assertTrue(restored.canDetachPlanningState((key, value) -> false), "unknown work is a fresh planning state");
		assertFalse(restored.isRuntimeTelemetryEnabled());
		assertFalse(restored.isExecutionSummaryEnabled());
	}

	@Test
	void genuineLegacyMapIndexMetricsPreserveZeroAndPositiveObservations() throws Exception {
		for (long expected : new long[] { 0L, 23L }) {
			String resource = expected == 0L ? "legacy-singleton-index-zero.ser"
					: "legacy-singleton-index-positive.ser";
			SingletonSet restored = readFixture(resource);
			assertEquals(expected, restored.getLongMetricActual(INDEX), resource);
			assertEquals(Long.valueOf(expected), restored.getLongMetricsActual().get(INDEX), resource);
			assertFalse(restored.canDetachPlanningState((key, value) -> false), "known work remains an observation");
			assertTrue(restored.isRuntimeTelemetryEnabled());
			assertFalse(restored.isExecutionSummaryEnabled());
		}
	}

	@Test
	void currentIndexMetricsPreserveUnknownZeroAndPositiveDespiteAnEarlierMapRead() throws Exception {
		for (long expected : new long[] { -1L, 0L, 23L }) {
			SingletonSet source = new SingletonSet();
			source.setRuntimeTelemetryEnabled(true);
			source.setLongMetricActual(INDEX, 7L);
			assertEquals(Long.valueOf(7L), source.getLongMetricsActual().get(INDEX));
			source.setLongMetricActual(INDEX, expected);
			SingletonSet restored = roundtrip(source);
			assertEquals(expected, restored.getLongMetricActual(INDEX), "a present primitive retains its exact value");
			assertEquals(Long.valueOf(expected < 0L ? 7L : expected), restored.getLongMetricsActual().get(INDEX));
		}
	}

